import{_ as e,o,c as i,a2 as l}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"隐私政策","description":"我们收集什么、如何使用、如何保护与你的权利。","frontmatter":{"title":"隐私政策","description":"我们收集什么、如何使用、如何保护与你的权利。","order":51,"group":"legal"},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),r={name:"privacy.md"};function t(c,a,d,n,s,h){return o(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="隐私政策-privacy-policy" tabindex="-1">隐私政策（Privacy Policy） <a class="header-anchor" href="#隐私政策-privacy-policy" aria-label="Permalink to &quot;隐私政策（Privacy Policy）&quot;">​</a></h1><blockquote><p>最后更新：2026-08-21</p></blockquote><h2 id="_1-收集的信息" tabindex="-1">1. 收集的信息 <a class="header-anchor" href="#_1-收集的信息" aria-label="Permalink to &quot;1. 收集的信息&quot;">​</a></h2><ul><li><strong>账户信息</strong>：用户名、邮箱、密码哈希、邀请链 <code>invited_by</code></li><li><strong>内容信息</strong>：你提交的元数据、帖子、媒体文件的 <code>sha256</code> 与 <code>technical_specs</code></li><li><strong>日志</strong>：<code>admin_audit_logs</code> 记录 L1 写入与 <code>asset_files</code> 访问的 <code>actor/target/ip/ua/时间</code></li><li><strong>技术信息</strong>：访问日志（Nginx <code>access.log</code>）、限流计数（Redis）、搜索关键词（ES/SQL）</li></ul><h2 id="_2-使用目的" tabindex="-1">2. 使用目的 <a class="header-anchor" href="#_2-使用目的" aria-label="Permalink to &quot;2. 使用目的&quot;">​</a></h2><ul><li>提供编目、检索、播放、下载、社区与审计功能</li><li>风控（邀请链溯源、限流、封禁）</li><li>统计与改进搜索/推荐质量</li></ul><h2 id="_3-存储与保护" tabindex="-1">3. 存储与保护 <a class="header-anchor" href="#_3-存储与保护" aria-label="Permalink to &quot;3. 存储与保护&quot;">​</a></h2><ul><li>密码仅存储哈希，<code>JWT_SECRET</code> 等敏感值通过环境变量注入，不落库明文</li><li>原档与预览分桶存储，预签名 URL 2 小时过期</li><li>ES 默认 <code>xpack.security.enabled=false</code> 仅适用于本地；公网部署需开启认证或置于内网</li></ul><h2 id="_4-共享" tabindex="-1">4. 共享 <a class="header-anchor" href="#_4-共享" aria-label="Permalink to &quot;4. 共享&quot;">​</a></h2><ul><li>不出售个人信息</li><li>仅在法律要求或为保护站务与用户权益时披露</li></ul><h2 id="_5-你的权利" tabindex="-1">5. 你的权利 <a class="header-anchor" href="#_5-你的权利" aria-label="Permalink to &quot;5. 你的权利&quot;">​</a></h2><ul><li>访问、更正、删除账户与个人数据（通过设置页或联系站务）</li><li>撤回授权、注销账号（将清理可识别信息，审计日志按合规保留）</li></ul><h2 id="_6-cookie-与本地存储" tabindex="-1">6. Cookie 与本地存储 <a class="header-anchor" href="#_6-cookie-与本地存储" aria-label="Permalink to &quot;6. Cookie 与本地存储&quot;">​</a></h2><ul><li>登录态存储于 <code>localStorage</code> 的 JWT，仅用于鉴权</li><li>文档站主题偏好存储于 <code>localStorage</code></li></ul><h2 id="_7-联系" tabindex="-1">7. 联系 <a class="header-anchor" href="#_7-联系" aria-label="Permalink to &quot;7. 联系&quot;">​</a></h2><p>隐私相关问题请见<a href="/docs/contact">联系方式</a>。</p>',16)])])}const p=e(r,[["render",t]]);export{u as __pageData,p as default};
